import os, glob, json
from collections import Counter, defaultdict
files = glob.glob(os.path.expanduser('~/.claude/projects/*/*.jsonl'))
files = sorted(files, key=lambda f: os.stat(f).st_mtime, reverse=True)[:50]

mcp = Counter(); skills = Counter(); slash = Counter()
hook_dur = defaultdict(list); hook_timeout = Counter()
# denials: map tool_use_id -> (tool, cmd) then find denial user entries
tooluse = {}   # id -> (name, input)
denials = []   # (toolname, keyed, kind)

for f in files:
    try:
        lines = open(f, encoding='utf-8').read().splitlines()
    except: continue
    for ln in lines:
        try: o = json.loads(ln)
        except: continue
        t = o.get('type')
        if t == 'assistant':
            for c in o.get('message',{}).get('content',[]) or []:
                if isinstance(c,dict) and c.get('type')=='tool_use':
                    nm = c.get('name',''); inp = c.get('input',{}) or {}
                    tooluse[c.get('id')] = (nm, inp)
                    if nm.startswith('mcp__'): mcp[nm]+=1
                    elif nm=='Skill':
                        s = inp.get('skill'); 
                        if s: skills[s]+=1
        elif t=='user':
            # slash commands
            cont = o.get('message',{}).get('content')
            txt = ''
            if isinstance(cont,str): txt=cont
            elif isinstance(cont,list):
                for c in cont:
                    if isinstance(c,dict) and c.get('type')=='text': txt+=c.get('text','')
                    if isinstance(c,dict) and c.get('type')=='tool_result':
                        pass
            if '<command-name>' in txt:
                import re
                for m in re.findall(r'<command-name>/?([^<]+)</command-name>', txt):
                    slash[m.strip()]+=1
            # denials
            dk = o.get('toolDenialKind')
            if dk and isinstance(cont,list):
                for c in cont:
                    if isinstance(c,dict) and c.get('type')=='tool_result':
                        tid = c.get('tool_use_id')
                        nm, inp = tooluse.get(tid,('?',{}))
                        key = nm
                        if nm=='Bash':
                            cmd = (inp.get('command','') or '').strip()
                            key = 'Bash: '+' '.join(cmd.split()[:2])
                        denials.append((key, dk))
        elif t=='attachment':
            a = o.get('attachment',{})
            if a.get('type','').startswith('hook_'):
                hn = a.get('hookName') or a.get('command','?')
                ev = a.get('hookEvent','?')
                d = a.get('durationMs')
                if d is not None: hook_dur[(hn,ev)].append(d)
                if a.get('timedOut'): hook_timeout[(hn,ev)]+=1

print("=== MCP tool calls ==="); [print(f"{v}\t{k}") for k,v in mcp.most_common()]
print("=== Skill dispatches ==="); [print(f"{v}\t{k}") for k,v in skills.most_common()]
print("=== Slash commands ==="); [print(f"{v}\t{k}") for k,v in slash.most_common(30)]
print("=== Denials (kind) ==="); dc=Counter(denials); [print(f"{v}\t{k}") for k,v in dc.most_common(30)]
print("=== Hook durations (event,count,typical_ms,max_ms) ===")
for (hn,ev),ds in sorted(hook_dur.items(), key=lambda x:-max(x[1])):
    ds2=sorted(ds); typ=ds2[len(ds2)//2]
    print(f"{ev}\tn={len(ds)}\ttyp={typ}\tmax={max(ds)}\t{hn[:60]}")
print("=== Hook timeouts ==="); [print(f"{v}\t{k}") for k,v in hook_timeout.most_common()]
EOF

